+++ b/src/orders.js
@@ -10,3 +10,14 @@
+async function listOrdersWithItems(db, customerId) {
+  const orders = await db.all('SELECT * FROM orders WHERE customer_id = ?', customerId);
+  for (const o of orders) {
+    o.items = await db.all('SELECT * FROM items WHERE order_id = ?', o.id);
+  }
+  return orders;
+}
+
+router.get('/orders', async (req, res) => {
+  res.json(await listOrdersWithItems(db, req.query.customerId));
+});

